# -*- coding: utf-8 -*-
# S7 (the assistant drawer) and S8 (the voice mode)

SUGG = [
    ("مالی", ["ریز مطالبات به تفکیک مشتری", "چک‌های سررسید ۳۰ روز آینده کدام‌اند؟"]),
    ("فروش", ["کدام پیشنهادها منتظر تایید من هستند؟", "دلایل باخت در ۱۲ ماه اخیر"]),
    ("پروژه‌ها", ["چه پروژه‌هایی قرمزند و چرا؟", "جریمه‌ی تاخیر هر پروژه چقدر است؟"]),
    ("تولید", ["سفارش‌های تولید عقب‌افتاده", "کدام مراکز کاری اضافه‌بار دارند؟"]),
    ("کیفیت", ["NCRهای باز عمده کدام‌اند؟", "اقدام‌های اصلاحی از مهلت گذشته"]),
    ("انبار", ["کالاهای زیر حداقل که تولید را متوقف می‌کنند", "ارزش کالاهای راکد چقدر است؟"]),
    ("تدارکات", ["ردیف‌های خرید با تاخیر تحویل", "تحویل به‌موقع تامین‌کنندگان اصلی"]),
    ("خدمات پس از فروش", ["درخواست‌های خارج از SLA", "هزینه‌ی گارانتی امسال به تفکیک ماه"]),
    ("دفتر", ["مصوبات جلسات از موعد گذشته", "نامه‌های منتظر اقدام من"]),
]
VOICE_CMDS = ["باز کن سفارش‌های عقب‌افتاده تولید", "بخوان هشدارها", "تحلیل کن بخش فروش", "نشانم بده پروژه‌های قرمز"]
GREETING = "سلام؛ چه کمکی از من برمی‌آید؟"
DEGRADED = "تحلیل هوشمند موقتاً در دسترس نیست؛ داشبورد اصلی همچنان در دسترس است."
NOTVERIFIED = "پاسخ مدل قابل راستی‌آزمایی نبود؛ نتایج مستقیم سامانه:"
EMPTY_HINT = ("بگویید یا بنویسید؛ دستیار پاسخ را می‌گوید و کارهایی مثل باز کردن جدول، تحلیل یک بخش یا خواندن هشدارها را انجام می‌دهد. "
              "با دسترسی‌های خود شما کار می‌کند و هیچ چیزی را تایید نمی‌کند.")
NO_SECURE = "گفت‌وگوی صوتی نیاز به اتصال امن (HTTPS یا localhost) دارد؛ گفت‌وگوی متنی در دسترس است"
BOX_HINT = "پرسش خود را بنویسید (Enter برای ارسال، Shift+Enter برای خط تازه)"


def _first_six():
    return "؛ ".join("%s: «%s»" % (s, q[0]) for s, q in SUGG[:6])


def _all_q():
    return "؛ ".join("%s: «%s» و «%s»" % (s, q[0], q[1]) for s, q in SUGG)


# ================================================================ S7
t("drawer_open", "S7", "کشوی «دستیار هوشمند»: بازکردن، چیدمان کنار یا روی صفحه، بستن، کپسول پایین صفحه و ماندن گفت‌وگو", CEO,
  [DASH + ": زیر خط «امروز …» دکمه‌ی «پرسش از دستیار» را بزنید. کشو از لبه‌ی چپ صفحه باز می‌شود.",
   "کشو را از بالا به پایین بخوانید: عنوان «دستیار هوشمند»، دکمه‌های «گفت‌وگوی تازه» و «تاریخچه»، متن راهنما، دو گروه دکمه‌ی کوچک (فرمان‌های صوتی و پرسش‌های پیشنهادی)، کادر پرسش با دکمه‌های «ارسال» و «میکروفون». ضربدر «بستن دستیار» بالای کشو است.",
   "پنجره‌ی مرورگر را در دو اندازه امتحان کنید (یا با Ctrl و + بزرگ‌نمایی را عوض کنید): عرض ⟦1280⟧ پیکسل یا بیشتر، و کمتر از آن (مثلاً نیم‌صفحه یا بزرگ‌نمایی ⟦175%⟧). هر بار کشو را ببندید و دوباره باز کنید. شکل ۷ نمونه‌ی ظاهر کشو را نشان می‌دهد.",
   "کشو را به سه راه ببندید: ضربدر، کلید Esc (وقتی مکان‌نما درون کشو است) و در حالت روی صفحه (با پرده‌ی تیره) زدن روی پرده‌ی تیره‌ی پشت آن. هر بار ببینید فوکوس کجا برمی‌گردد.",
   "با کشوی بسته، نوار گوشه‌ی پایین‌چپ صفحه را ببینید و دکمه‌ی «دستیار هوشمند» آن را بزنید.",
   "یک پرسش بنویسید و بفرستید (مثلاً «سلام»)، کشو را ببندید و دوباره باز کنید."],
  "کشو زیر نوار بالای برنامه باز می‌شود (در گوشی از بالای صفحه) و مکان‌نما بلافاصله در کادر پرسش است. عنوان «دستیار هوشمند»؛ دو دکمه‌ی «گفت‌وگوی تازه» و «تاریخچه»؛ متن خالی: «%s»؛ کادر پرسش با راهنمای «%s»؛ دکمه‌ی «ارسال» (تا چیزی ننوشته‌اید خاکستری است) و «میکروفون». در پنجره‌ی با عرض ⟦1280⟧ پیکسل یا بیشتر کشو کنار صفحه می‌نشیند: ⟦400⟧ پیکسل جا می‌گیرد، محتوای صفحه برای آن جمع می‌شود و پرده‌ی تیره ندارد. در عرض کمتر کشو روی صفحه می‌افتد (حداکثر ⟦420⟧ پیکسل، در گوشی تمام‌عرض) و پشت آن پرده‌ی تیره دیده می‌شود. ضربدر (راهنمای «بستن دستیار (Esc)»)، Esc و پرده‌ی تیره کشو را می‌بندند و فوکوس به همان دکمه‌ای برمی‌گردد که کشو را باز کرده بود. با کشوی بسته، کپسول گوشه‌ی پایین‌چپ دکمه‌ی «دستیار هوشمند» دارد و اگر مرورگر و نشانی «امن» باشد یک دکمه‌ی میکروفون هم (آزمون @v_support@)؛ با بازشدن کشو کپسول ناپدید می‌شود. پرسش‌ها و پاسخ‌ها با بستن کشو از بین نمی‌روند؛ با F5 یا رفتن به صفحه‌ی دیگر صفحه‌ی گفت‌وگو خالی می‌شود، ولی گفت‌وگو در «تاریخچه» می‌ماند (آزمون @drawer_history@)." % (EMPTY_HINT, BOX_HINT))

t("drawer_suggest", "S7", "دکمه‌های فرمان صوتی و پرسش‌های پیشنهادی کشو (ترتیب، شش‌تایی، «همه‌ی پرسش‌ها»، پر شدن کادر بدون ارسال)", CEO,
  [DASH + ": کشو را باز کنید. عنوان گروه‌ها را بخوانید: «فرمان‌های صوتی؛ بگویید یا بزنید» و «پرسش‌های پیشنهادی».",
   "اشاره‌گر را روی چند دکمه نگه دارید و راهنمای هر کدام را بخوانید. دکمه‌های پرسش را بشمارید و ترتیب‌شان را با رنگ نُه چراغ بالای صفحه مقایسه کنید.",
   "«همه‌ی پرسش‌ها» را بزنید و دکمه‌ها را بشمارید؛ دوباره (حالا «پرسش‌های کمتر») بزنید.",
   "روی یک دکمه‌ی پرسش بزنید (مثلاً «NCRهای باز عمده کدام‌اند؟»). کادر پرسش و فهرست گفت‌وگو را ببینید، چند ثانیه چیزی نزنید، سپس «ارسال» را بزنید.",
   "پاسخ مدل آزمایشی را بخوانید. همین کار را با دکمه‌ی «ریز مطالبات به تفکیک مشتری» تکرار کنید."],
  "گروه «فرمان‌های صوتی؛ بگویید یا بزنید» چهار دکمه دارد، به این ترتیب: «%s». راهنمای هر کدام «همین حالا انجام می‌شود» است، چون زدن روی آن‌ها پرسش را بی‌درنگ می‌فرستد (آزمون @v_act@). گروه «پرسش‌های پیشنهادی» به‌طور پیش‌فرض شش دکمه دارد: نخستین پرسش شش بخشِ فوری‌تر؛ فوری‌ترین بخش یعنی بخشی که چراغش قرمز است، سپس کهربایی، سپس سبز و سپس بدون داده، و بخش‌های هم‌رنگ به ترتیب صفحه‌اند (مالی، فروش، پروژه‌ها، تولید، کیفیت، انبار، تدارکات، خدمات پس از فروش، دفتر). اگر همه سبز باشند شش دکمه این‌هاست: %s. راهنمای هر دکمه «بخش <نام بخش>» است. «همه‌ی پرسش‌ها» ۱۸ دکمه (دو پرسش برای هر بخش) نشان می‌دهد: %s. زدن روی دکمه‌ی پرسش فقط کادر پرسش را پر می‌کند و مکان‌نما را آخر آن می‌گذارد؛ چیزی فرستاده نمی‌شود و فهرست گفت‌وگو تغییر نمی‌کند. با «ارسال» (یا Enter) فرستاده می‌شود. مدل آزمایشی به ۱۷ از ۱۸ پرسش پاسخ سلام می‌دهد: «%s» (خطا نیست، چون هیچ واژه‌ی کلیدی ندارند)؛ فقط «ریز مطالبات به تفکیک مشتری» به‌خاطر واژه‌ی «ریز» پاسخ جدول جزئیات می‌گیرد: «طبق نتایج سامانه: N، 1، 5» که N شمار گزارش‌های عدم انطباق باز است، نه مطالبات (آزمون @drawer_drill@)." % (
      "»، «".join(VOICE_CMDS), _first_six(), _all_q(), GREETING))

t("drawer_ask", "S7", "«پرسش از دستیار درباره‌ی این جدول»: کادر پر می‌شود و چیزی فرستاده نمی‌شود", CEO,
  [DASH + ": روی کاشی «گزارش‌های عدم انطباق باز» (شاخص‌های اصلی) بزنید تا جدول جزئیات باز شود.",
   "دکمه‌ی «پرسش از دستیار درباره‌ی این جدول» (بالای جدول) را بزنید.",
   "ببینید پنجره‌ی جدول و کشو چه می‌شوند و در کادر پرسش چه نوشته است. پنج ثانیه چیزی نزنید.",
   "«ارسال» را بزنید.",
   "(شرطی) در آزمون @pmomask@ جدول «هزینه‌ی گارانتی به تفکیک ماه» را با کاربر معاونت PMO باز کنید و حالت این دکمه را ببینید."],
  "پنجره‌ی جدول بسته می‌شود، کشو باز می‌شود و در کادر پرسش (بدون ارسال) این متن است: «درباره‌ی جدول «گزارش‌های عدم انطباق باز» توضیح بده: مهم‌ترین ردیف‌ها، تغییر نسبت به ماه قبل و ریسک‌ها کدام‌اند؟» (نام جدول همان عنوان جدول باز است). فهرست گفت‌وگو تا زدن «ارسال» تغییر نمی‌کند و مکان‌نما آخر متن است؛ می‌شود متن را عوض کرد. پس از «ارسال» نشان «در حال پاسخ‌دادن…» و سپس پاسخ می‌آید؛ مدل آزمایشی چون واژه‌ی کلیدی در پرسش نیست می‌گوید «%s» (یک مدل واقعی از ابزارهای جزئیات و نمای کلی استفاده می‌کند). دکمه‌ی «پرسش از دستیار درباره‌ی این جدول» تا خوانده‌شدن جدول خاکستری است و برای جدولی که مبلغ حقوق دارد و برای نقش شما پنهان است (قفل «محرمانه (حقوق)») هم خاکستری می‌ماند." % GREETING)

t("drawer_drill", "S7", "پرسش تایپی «ریز …»، «فهرست جزئیات» و «تحلیل»: جواب با عدد، پیوندها، نشان راستی‌آزمایی و ابزارهای استفاده‌شده", CEO,
  ["در کشو بنویسید «ریز گزارش‌های عدم انطباق باز» و Enter بزنید. نشان «در حال پاسخ‌دادن…» را ببینید و پاسخ را بخوانید.",
   "زیر پاسخ: نشان‌ها، نام مدل، متن، دکمه‌های پیوند و «ابزارهای استفاده‌شده (N)» را بخوانید و فهرست ابزارها را باز کنید. روی دکمه‌ی اول و سپس روی یکی از دکمه‌های «گزارش عدم انطباق …» بزنید و با کلید برگشت مرورگر بازگردید (گفت‌وگو پس از بازگشت خالی است؛ آزمون @drawer_history@).",
   "عدد اول پاسخ را با کاشی «گزارش‌های عدم انطباق باز» مقایسه کنید.",
   "بنویسید «فهرست جزئیات را بگو» و بفرستید. سپس «تحلیل کل شرکت را بگو».",
   "در کادر پرسش Shift+Enter بزنید؛ سپس همه‌ی متن را پاک کنید و دکمه‌ی «ارسال» را ببینید."],
  "پاسخ اول: خط «شما» با متن پرسش و زیر آن «دستیار» با نشان سبز «راستی‌آزمایی‌شده» (راهنما: «اعداد پاسخ با داده‌های سامانه سنجیده شد»)، نام مدل ⟦mock-primary⟧ و متن «طبق نتایج سامانه: N، 1، 5». N شمار کل گزارش‌های عدم انطباق باز است (برابر کاشی، و برابر «N ردیف» زیر عنوان جدول)، عدد ۱ شماره‌ی صفحه و عدد ۵ تعداد ردیف‌هایی است که مدل آزمایشی خواسته است. زیر متن دکمه‌های پیوند: نخستین با عنوان جدول «گزارش‌های عدم انطباق باز» (صفحه‌ی ⟦/inventory/ncr⟧) و تا پنج دکمه‌ی «گزارش عدم انطباق <شماره>» که گزارش همان ردیف را باز می‌کنند (راهنما «باز کردن رکورد»)؛ دکمه‌ای که صفحه‌اش برای نقش شما باز نمی‌شود خاکستری است و راهنمای «صفحه این رکورد در دسترس نیست» دارد. «ابزارهای استفاده‌شده (1)» فقط ⟦ceo_drill⟧ را دارد، بدون نشان «بدون دسترسی». پاسخ دوم: «ابزارهای جزئیات در دسترس است.» (ابزار ⟦ceo_drills⟧، بدون عدد). پاسخ سوم: «طبق نتایج سامانه: …» با حداکثر سه عدد از نمای کلی (ابزار ⟦ceo_overview⟧)؛ همه راستی‌آزمایی‌شده‌اند چون عدد دیگری نگفته‌اند. Enter می‌فرستد و Shift+Enter خط تازه می‌سازد؛ «ارسال» با کادر خالی خاکستری است و کادر بیشتر از ⟦2000⟧ نویسه نمی‌گیرد. (یک مدل واقعی این ابزارها را برای پرسش‌هایی مثل «ریز مطالبات به تفکیک مشتری» با کلید درست جدول صدا می‌زند؛ مدل آزمایشی همیشه جدول گزارش‌های عدم انطباق را می‌خواهد.)")

t("drawer_nav", "S7", "فرمان‌های «باز کن …» و «بخوان هشدارها» به‌صورت تایپی: صفحه‌ی ماژول، همین صفحه، خواندن هشدارها", CEO,
  ["در کشو بنویسید «باز کن سفارش‌های تولید» و Enter بزنید. پاسخ و خط زیر آن را بخوانید و ببینید چه می‌شود.",
   "با کلید برگشت مرورگر به داشبورد برگردید، کشو را باز کنید و بنویسید «باز کن پیوند عددی».",
   "بنویسید «بخوان هشدارها» و بفرستید. به ستون هشدارها و به کپسول یا کادر صدای کشو نگاه کنید.",
   "(صفحه‌ی کوچک) همین را در پنجره‌ای کم‌عرض‌تر از ⟦1280⟧ پیکسل تکرار کنید و ببینید کشو چه می‌شود."],
  "گام ۱: پاسخ «سفارش‌های تولید را باز می‌کنم.»؛ زیر آن خط «✓ صفحه‌ی «باز کردن صفحه‌ی تولید» پس از پایان پاسخ باز می‌شود». چون پرسش تایپ شده و پاسخ گفته نمی‌شود، صفحه همان لحظه به صفحه‌ی سفارش‌های تولید (⟦/production/orders⟧) می‌رود (برای مدیرعامل و معاونت PMO مجاز است). ابزار ⟦ui_navigate⟧، نشان «راستی‌آزمایی‌شده». گام ۲: همان پاسخ ثابت، و خط «✓ همین صفحه باز است»؛ صفحه جابه‌جا نمی‌شود (پیوند ⟦/ceo?x=…⟧ به همین صفحه می‌رسد). عدد داخل پیوند هرگز در پاسخ یا نتیجه نمی‌آید و نشان «راستی‌آزمایی‌شده» می‌ماند. گام ۳: پاسخ «هشدارها را می‌خوانم.»، خط «✓ هشدارها خوانده می‌شود»؛ صفحه به ستون هشدارها می‌رود و فهرست هشدارها با صدا خوانده می‌شود (با مدل آزمایشی صدا یک مکث ⟦0.1⟧ ثانیه‌ای بی‌صداست؛ برای دیدن متن، آزمون @speakalerts@)؛ پاسخ خود مدل گفته نمی‌شود و پس از خواندن پنجره‌ی «پرسش بعدی» باز نمی‌شود، چون پرسش تایپی بود. گام ۴: در صفحه‌ی کم‌عرض کشو پیش از نمایش نتیجه بسته می‌شود تا ستون هشدارها دیده شود؛ در فرمان «باز کن …» کشو تا رفتن به صفحه‌ی دیگر می‌ماند.")

t("drawer_safe", "S7", "ایمنی دستیار: صفحه‌ی بیرونی رد می‌شود، عدد جعلی راستی‌آزمایی نمی‌شود، نقش بی‌دسترسی رد می‌شود", CEO + " و " + WU,
  ["مدیرعامل، در کشو بنویسید «بیرون» و بفرستید. نتیجه را بخوانید (صفحه نباید جابه‌جا شود).",
   "بنویسید «جعل» و بفرستید. نشان، متن پاسخ و ابزارها را بخوانید.",
   "از برنامه خارج شوید و با کاربر انباردار آزمایشی وارد شوید: هوش مصنوعی ← دستیار هوشمند. بنویسید «اجبار ریز» و بفرستید؛ سپس فهرست «ابزارهای استفاده‌شده» را باز کنید.",
   "همان‌جا بنویسید «داشبورد مدیرعامل را بگو» و بفرستید."],
  "گام ۱: پاسخ «این صفحه برای باز شدن مجاز نیست.»؛ هیچ خط «✓»، هیچ دکمه‌ی باز کردن و هیچ جابه‌جایی نیست (سرور پیوندی را که از فهرست صفحه‌های مجاز نباشد نمی‌پذیرد). گام ۲: مدل آزمایشی نتیجه‌ی داشبورد را می‌گیرد ولی می‌نویسد «مبلغ کل 987654321 ریال است.»، عددی که در هیچ نتیجه‌ی سامانه نیست؛ پس نشان قرمز «راستی‌آزمایی‌نشده» می‌آید، متن با «%s» شروع می‌شود و نتیجه‌ی مستقیم سامانه را نشان می‌دهد، و عدد جعلی در متن نهایی نیست. گام ۳: پاسخ «شما به این اطلاعات دسترسی ندارید.»؛ در «ابزارهای استفاده‌شده» ابزار ⟦ceo_drill⟧ با نشان قرمز «بدون دسترسی» است و هیچ داده‌ای نمی‌آید (جدول‌های جزئیات فقط برای مدیرعامل و معاونت PMO است). گام ۴: پاسخ «این ابزار برای شما در دسترس نیست.» (ابزار نمای داشبورد به انباردار پیشنهاد نمی‌شود)." % NOTVERIFIED)

t("drawer_history", "S7", "گفت‌وگوی تازه و تاریخچه‌ی گفت‌وگوها (فقط گفت‌وگوهای خود کاربر)", CEO,
  ["در کشو دو پرسش بفرستید (مثلاً «ریز گزارش‌های عدم انطباق باز» و «فهرست جزئیات را بگو»).",
   "«گفت‌وگوی تازه» را بزنید و ببینید فهرست چه می‌شود؛ سپس بنویسید «سلام» و بفرستید.",
   "«تاریخچه» را بزنید. عنوان پنجره، ردیف‌ها و زیر هر ردیف را بخوانید. گفت‌وگوی قدیمی‌تر را بزنید.",
   "پرسش تازه‌ای در همان گفت‌وگو بفرستید. «بستن» را بزنید.",
   "F5 بزنید، کشو را باز کنید و دوباره «تاریخچه» را ببینید.",
   "با کاربر معاونت PMO وارد شوید و «تاریخچه»‌ی همان کشو را باز کنید."],
  "«گفت‌وگوی تازه» پرسش‌ها را از صفحه برمی‌دارد و متن خالی راهنما برمی‌گردد؛ پرسش بعدی گفت‌وگوی تازه‌ای می‌سازد. «تاریخچه» پنجره‌ی «تاریخچه گفت‌وگوها» را باز می‌کند: هر ردیف عنوان گفت‌وگو (نخستین پرسش، یا «گفت‌وگو <شماره>») و زیر آن «<تاریخ و ساعت شمسی> — N پیام» دارد (هر پرسش و پاسخ آن دو پیام است)، تازه‌ترین بالاست و گفت‌وگوی بازشده برجسته است (اگر خالی بود: «گفت‌وگویی ثبت نشده است.»). زدن روی ردیف، پرسش‌ها و پاسخ‌های آن گفت‌وگو را با نام مدل و نشان راستی‌آزمایی می‌آورد (بدون دکمه‌های پیوند و ابزار، چون آن‌ها ذخیره نمی‌شوند) و پرسش تازه به همان گفت‌وگو افزوده می‌شود (شمار «N پیام» بالا می‌رود). دکمه‌های «گفت‌وگوی تازه» و «تاریخچه» تا رسیدن پاسخ یا هنگام ضبط صدا خاکستری‌اند. پس از F5 صفحه‌ی گفت‌وگو خالی است ولی تاریخچه همه‌ی گفت‌وگوها را دارد. کاربر معاونت PMO فقط گفت‌وگوهای خودش را می‌بیند، نه گفت‌وگوهای مدیرعامل را. (همین پنل در «هوش مصنوعی ← دستیار هوشمند» برای همه‌ی کاربران هست؛ گفت‌وگوها در دو جا یکی‌اند.)")


# ================================================================ S8
t("v_support", "S8", "پشتیبانی صدا: کپسول پایین صفحه، میکروفون، اجازه‌ی مرورگر و حالت بدون میکروفون (نشانی ناامن)", CEO,
  ["روی ماشین سرور، در مرورگر ⟦http://localhost⟧ را باز کنید و با کاربر مدیرعامل به داشبورد بروید (نشانی ⟦localhost⟧ و هر نشانی ⟦https⟧ «امن» حساب می‌شود). کشو را ببندید، گوشه‌ی پایین‌چپ صفحه را ببینید و اشاره‌گر را روی دکمه‌ی میکروفون نگه دارید.",
   "دکمه‌ی میکروفون را یک بار بزنید. اگر مرورگر اجازه‌ی میکروفون پرسید، «Allow» (اجازه‌دادن) را بزنید. نشانگر ضبط مرورگر (نقطه‌ی قرمز یا نماد میکروفون روی زبانه یا نوار آدرس) را ببینید و سپس Esc بزنید.",
   "از رایانه‌ی دیگری در شبکه، برنامه را با نام یا IP ماشین سرور و بدون https باز کنید (مثلاً ⟦http://SERVER-NAME⟧) و با مدیرعامل به داشبورد بروید. کپسول را ببینید، کشوی «دستیار هوشمند» را باز کنید، دکمه‌ی «میکروفون» و متن کوچک زیر کادر پرسش را بخوانید و یک پرسش تایپی بفرستید. سپس روی بخش خالی صفحه Space بزنید.",
   "(شرطی؛ مرورگری که ضبط صدا با قالب webm یا ogg ندارد) گام قبل را در آن مرورگر هم انجام دهید و متن زیر کادر را بخوانید."],
  "گام ۱: کپسول فقط وقتی کشو بسته است دیده می‌شود (شکل ۸ آن را هنگام شنیدن نشان می‌دهد) و دو دکمه دارد: میکروفون (راهنما «صحبت با دستیار (یا Space را نگه دارید)») و «دستیار هوشمند» که کشو را باز می‌کند. گام ۲: مرورگر در نخستین استفاده اجازه می‌خواهد؛ پس از «Allow» کارتی بالای کپسول با «در حال شنیدن…»، موج صدا و جمله‌ی «بگویید؛ پس از مکثی کوتاه ارسال می‌شود.» باز می‌شود، با Esc بسته می‌شود و نشانگر ضبط مرورگر همان لحظه خاموش می‌شود (میکروفون فقط هنگام گوش‌دادن باز است؛ ضبط دائمی و واژه‌ی بیدارکننده وجود ندارد). گام ۳: در نشانی ناامن کپسول فقط دکمه‌ی «دستیار هوشمند» دارد؛ در کشو دکمه‌ی «میکروفون» خاکستری و غیرفعال است و راهنمای آن و متن کوچک زیر کادر این است: «%s». پرسش تایپی بی‌مشکل جواب می‌دهد و Space صفحه را مثل همیشه پایین می‌برد (برای صدا گرفته نمی‌شود). گام ۴: متن کوچک «این مرورگر ضبط صدا با قالب پشتیبانی‌شده (webm یا ogg) را ندارد؛ گفت‌وگوی متنی در دسترس است». رایانه‌ی مدیرعامل برای صدا به نشانی امن (HTTPS) نیاز دارد؛ روش آن تصمیم شرکت است (★ پرسش‌های شرکت، و بخش «میکروفون و نشانی امن» راهنما)." % NO_SECURE)

t("speakhead", "S8", "خواندن خلاصه‌ی شاخص‌های اصلی با صدا (نماد بلندگو): توقف، متن گفته‌شده و تطبیق با صفحه", CEO,
  [DASH + ": کشو بسته باشد. نماد بلندگوی کنار عنوان «شاخص‌های اصلی» را ببینید و اشاره‌گر را روی آن نگه دارید.",
   "نماد را بزنید. به نماد، به کارت بالای کپسول پایین‌چپ و به صدا توجه کنید. (با مدل آزمایشی صدا یک مکث ⟦0.1⟧ ثانیه‌ای بی‌صداست؛ کارت پس از پایان صدا حدود پنج ثانیه با متن آخرین جمله می‌ماند.)",
   "دوباره نماد را بزنید و میان گفتن، یک بار دیگر آن را بزنید. سپس دوباره بزنید و میان گفتن Esc بزنید. (برای زمان بیشتر، سرور «متن به گفتار» را در «" + AIM + "سرورهای هوش مصنوعی» غیرفعال کنید؛ متن حداکثر ⟦6⟧ ثانیه در کارت می‌ماند. پس از آزمون دوباره فعالش کنید.)",
   "برای تطبیق متن: در رابط برنامه‌نویسی (Swagger؛ روش ورود در آزمون @apirefusal@) با توکن مدیرعامل ⟦GET /api/v1/ceo/speech?what=headline⟧ را اجرا کنید و متن را با هشت کاشی و نُه چراغ صفحه مقایسه کنید."],
  "گام ۲: نماد به علامت توقف تبدیل می‌شود (راهنما «توقف خواندن»؛ نماد بقیه‌ی بخش‌ها همان بلندگو می‌ماند). کارت ابتدا لحظه‌ای «در حال فکر کردن…» (نوار باریک در حال حرکت) و سپس «در حال گفتن…» را نشان می‌دهد و متن گفته‌شده در آن است؛ پس از پایان صدا نماد دوباره بلندگو می‌شود. خلاصه‌خوانی پنجره‌ی «پرسش بعدی» باز نمی‌کند (شمارنده نمی‌آید). گام ۳: زدن دوباره‌ی همان نماد یا Esc گفتن را می‌ایستاند و کارت بسته می‌شود؛ بلندگو دوباره آماده است. گام ۴: پاسخ ⟦success: true⟧ با سه مقدار در data: text، audioBase64 (با سرور «متن به گفتار» روشن پر است؛ با خاموش بودن آن خالی و degraded برابر true) و degraded. text با «خلاصه‌ی وضعیت شرکت در <تاریخ امروز با حروف>.» شروع می‌شود، سپس برای هر یک از هشت کاشی یک جمله به ترتیب صفحه می‌آید: «<عنوان؛ بدون یادداشت لاتین مثل backlog> <مقدار>»؛ مبلغ ریالی با سه رقم معنی‌دار گرد و با حروف گفته می‌شود (۴۸٬۲۳۴٬۵۶۷٬۸۹۰ ریال می‌شود «چهل و هشت میلیارد و دویست میلیون ریال»)، بعد «، X بیشتر از ماه پیش» یا «کمتر از ماه پیش» یا «، بدون تغییر نسبت به ماه پیش» (اگر ماه پیش داده دارد) و برای کاشی هشدار «؛ نیازمند توجه» و برای بحرانی «؛ در وضعیت خطر»؛ کاشی بی‌عدد «… در دسترس نیست». پایان متن: «بخش‌های در وضعیت خطر: …» و «بخش‌های نیازمند توجه: …» با نام بخش‌هایی که چراغشان قرمز یا کهربایی است، یا «هیچ بخشی هشدار ندارد». عددها همان عددهای صفحه‌اند، فقط به حروف. این خواندن مدل زبانی لازم ندارد و با خاموش بودن همه‌ی مدل‌ها هم کار می‌کند (آزمون @aidown@)؛ فقط اگر سرور «متن به گفتار» خاموش باشد صدا نمی‌آید و متن در کپسول می‌ماند (آزمون @speechdown@).")

t("speaksec", "S8", "خواندن یک بخش با صدا (بلندگوی سرصفحه‌ی بخش): جمله‌ها، شمار شاخص‌های خطر و خواندن جابه‌جا", CEO,
  [DASH + ": کشو بسته باشد. سرصفحه‌ی بخش «مالی» را ببینید؛ سه نماد کوچک دارد (بخوان، جزئیات، تحلیل هوشمند). اشاره‌گر را روی هر کدام نگه دارید و راهنمایش را بخوانید. سپس نماد بلندگو را بزنید.",
   "میان گفتن، نماد بلندگوی بخش «فروش» را بزنید. سپس همان نماد را دوباره بزنید.",
   "برای تطبیق متن: در Swagger با توکن مدیرعامل ⟦GET /api/v1/ceo/speech?what=section&sectionKey=finance⟧ را اجرا کنید و با شاخص‌های بخش مالی مقایسه کنید. همین را برای بخشی که چراغش قرمز است و بخشی که همه‌ی عددهایش صفر است تکرار کنید (کلید بخش‌ها: ⟦finance⟧، ⟦sales⟧، ⟦projects⟧، ⟦production⟧، ⟦quality⟧، ⟦inventory⟧، ⟦procurement⟧، ⟦service⟧، ⟦office⟧).",
   "در Swagger: ⟦what=section⟧ بدون sectionKey، سپس ⟦what=section&sectionKey=xyz⟧ و ⟦what=abc⟧ را اجرا کنید."],
  "گام ۱: بلندگوی بخش مالی به علامت توقف تبدیل می‌شود (راهنما «توقف خواندن»؛ راهنمای حالت عادی «بخوان: خلاصه‌ی صوتی») و کارت کپسول «در حال گفتن…» با متن را نشان می‌دهد؛ نمادهای بقیه‌ی بخش‌ها تغییر نمی‌کنند. گام ۲: خواندن مالی قطع می‌شود و خواندن فروش شروع می‌شود (در هر لحظه فقط یک نماد علامت توقف دارد)؛ زدن دوباره آن را می‌ایستاند. گام ۳: text با «بخش مالی» شروع می‌شود؛ بعد اگر شاخصی بحرانی یا هشدار دارد «N شاخص در وضعیت خطر و M شاخص نیازمند توجه است» (هر کدام صفر بود نمی‌آید) و اگر هیچ‌کدام: «هیچ شاخصی از این بخش هشدار ندارد»؛ سپس یک جمله برای هر یک از شاخص‌های بخش، به ترتیب صفحه، با همان ساختار آزمون @speakhead@ (مبلغ گرد‌شده و با حروف، تغییر نسبت به ماه پیش، «؛ در وضعیت خطر» یا «؛ نیازمند توجه»). بخشی که محاسبه‌اش شکست خورده (در کار عادی پیش نمی‌آید) فقط نامش و یادداشت «اطلاعات این بخش اکنون در دسترس نیست؛ …» را می‌گوید. شاخص پنهان برای معاونت PMO «<عنوان> محرمانه است» گفته می‌شود (آزمون @pmomask@). گام ۴: به ترتیب «برای خلاصه‌ی صوتی یک بخش، کلید بخش را بفرستید.»؛ «بخش داشبورد پیدا نشد.»؛ «نوع خلاصه‌ی صوتی معتبر نیست؛ یکی از headline، section، alerts یا brief را بفرستید.» (در هر سه success برابر false است و خطای سرور نیست).")

t("speakalerts", "S8", "خواندن هشدارها با صدا (بلندگوی ستون هشدارها): شمار، ترتیب، حداکثر ده مورد", CEO,
  [DASH + ": کشو بسته باشد. عنوان «هشدارها» در ستون هشدارها را ببینید؛ نماد بلندگو کنار آن است. شمار هر گروه («بحرانی»، «هشدار»، «اطلاع») را از یادداشت‌های آزمون @base@ بردارید.",
   "نماد را بزنید و به کارت کپسول و صدا توجه کنید. دوباره بزنید تا بایستد.",
   "برای تطبیق متن: در Swagger با توکن مدیرعامل ⟦GET /api/v1/ceo/speech?what=alerts⟧ را اجرا کنید و با ستون هشدارها مقایسه کنید.",
   "(شرطی) اگر بیش از ده هشدار دارید، انتهای متن Swagger را ببینید. اگر هیچ هشداری نیست، نماد بلندگو در ستون نیست؛ متن را فقط از Swagger بخوانید."],
  "گام ۲: نماد به علامت توقف تبدیل می‌شود (راهنما «توقف خواندن»؛ حالت عادی «بخوان: هشدارها») و فهرست خوانده می‌شود. گام ۳: text با «N هشدار برای امروز ثبت شده است؛ a مورد خطر، b مورد هشدار و c مورد اطلاع» شروع می‌شود (گروهی که صفر است نمی‌آید؛ N برابر جمع سه گروه ستون هشدارها؛ گروه «بحرانی» صفحه با کلمه‌ی «خطر» گفته می‌شود). بعد حداکثر ده هشدار، بدترین‌ها اول و به ترتیب همان ستون، هر کدام با «خطر،» یا «هشدار،» یا «اطلاع،» و متن هشدار؛ اگر بیش از ده است، در آخر «M هشدار دیگر را در داشبورد ببینید» (M برابر N منهای ده). بدون هشدار: ستون پیام «هشداری نیست؛ همه‌ی ماژول‌ها در وضعیت عادی‌اند.» را می‌نویسد، نماد بلندگو نیست و Swagger «هشداری برای امروز ثبت نشده است.» می‌دهد. متن از همان داده‌ی در حافظه‌ی موقت صفحه ساخته می‌شود؛ پس هر چه می‌گوید با صفحه یکی است. فرمان تایپی «بخوان هشدارها» (آزمون @drawer_nav@) همین متن را می‌خواند.")

t("speakbrief", "S8", "گزارش روزانه با صدا: «پخش گزارش صوتی» و خلاصه‌ی صوتی گزارش از رابط (فقط مدیرعامل)", CEO + " و " + PMO,
  [DASH + ": پس از ساخته‌شدن گزارش (آزمون @brief@) در کارت «گزارش روزانه» روی «پخش گزارش صوتی» بزنید. نوار پخش را ببینید و صدا را متوقف کنید.",
   "در Swagger با توکن مدیرعامل ⟦GET /api/v1/ceo/speech?what=brief⟧ را اجرا کنید. (برای دیدن پیام «هنوز گزارش» این گام را پیش از ساخت گزارش هم بزنید.)",
   "همین را با توکن معاونت PMO تکرار کنید."],
  "گام ۱: کنار دکمه چرخنده‌ی کوچک می‌چرخد و بعد زیر متن گزارش نوار پخش (دکمه‌ی پخش و توقف) می‌آید و گزارش گفته می‌شود (با مدل آزمایشی مکث ⟦0.1⟧ ثانیه‌ای بی‌صدا). اگر سرور «متن به گفتار» نباشد پیام «سرویس گفتار در دسترس نیست؛ پاسخ فقط به‌صورت متن ارائه شد.» دیده می‌شود. گام ۲: text با «گزارش روزانه‌ی مدیرعامل در <تاریخ روز گزارش با حروف>.» شروع می‌شود و متن گزارش (با عددها به حروف) پشت آن می‌آید؛ اگر هنوز گزارشی نیست success برابر false است و پیام «هنوز گزارش روزانه‌ای ساخته نشده است.». گام ۳: «شما مجوز این کار را ندارید.»؛ گزارش فقط برای مدیرعامل خوانده می‌شود، چون با عددهای مخصوص او نوشته شده است. (دستور «گزارش روزانه را بخوان» به دستیار با یک مدل واقعی همین گزارش را برای مدیرعامل می‌خواند و برای معاونت PMO می‌گوید «گزارش روزانه فقط برای مدیرعامل خوانده می‌شود»؛ مدل آزمایشی این کار را نمی‌کند و جمله‌ی «گزارش روزانه» را به ابزار داشبورد می‌دهد.)")

t("v_listen", "S8", "پرسش با میکروفون (یک ضربه): شنیدن، فکر کردن، گفتن، پنجره‌ی «پرسش بعدی» و ارسال فوری", CEO,
  [DASH + ": کشو بسته باشد. دکمه‌ی میکروفون کپسول را یک بار بزنید. پس از دیدن «در حال شنیدن…» نیم ثانیه صبر کنید (در این مدت میکروفون صدای اتاق را می‌سنجد)، سپس با صدای عادی بگویید «وضعیت شرکت چطور است؟» و ساکت بمانید. (هر جمله‌ای بگویید؛ مدل آزمایشی گفتار را نمی‌فهمد و همیشه «خلاصه داشبورد مدیرعامل» می‌شنود.)",
   "حالت کارت را مرحله به مرحله دنبال کنید و پاسخ را بخوانید. پس از پایان گفتن چیزی نگویید و شمارنده را تا صفر ببینید.",
   "دوباره میکروفون را بزنید، یک جمله‌ی کوتاه بگویید و بی‌انتظار مکث، دوباره میکروفون را بزنید.",
   "دوباره میکروفون را بزنید و ⟦8⟧ ثانیه هیچ نگویید.",
   "کشو را باز کنید و گام‌های ۱ و ۲ را با دکمه‌ی «میکروفون» کشو انجام دهید. سپس «گفت‌وگوی پیوسته» را خاموش کنید و دوباره بپرسید."],
  "گام ۱ و ۲: کارت بالای کپسول به ترتیب نشان می‌دهد: «در حال شنیدن…» با موج صدا و جمله‌ی «بگویید؛ پس از مکثی کوتاه ارسال می‌شود.» (شکل ۸)؛ حدود ⟦1.2⟧ ثانیه پس از پایان گفتار خودکار فرستاده می‌شود: «در حال فکر کردن…» (نوار باریک در حال حرکت)؛ «در حال گفتن…» با متن پاسخ. پاسخ مدل آزمایشی «طبق نتایج سامانه: A، B، C» است؛ سه عدد اول نتیجه‌ی ابزار «داشبورد مدیرعامل» (به ترتیب ارزش موجودی، شمار کالاهای زیر حداقل، شمار ردیف‌های قرنطینه؛ در پایگاه خالی «0، 0، 0»)، نه هشت شاخص اصلی. سپس پنجره‌ی «پرسش بعدی»: کارت «پرسش بعدی را بگویید» با شمارنده‌ای از ⟦۶⟧ تا ⟦۰⟧ با ارقام فارسی (راهنما «پنجره‌ی پرسش بعدی»)؛ اگر بگویید همان چرخه تکرار می‌شود، و اگر ⟦6⟧ ثانیه چیزی نگویید میکروفون بی‌پیام بسته می‌شود (نشانگر ضبط مرورگر خاموش) و کارت حدود پنج ثانیه آخرین جمله را نگه می‌دارد. در فهرست کشو (آزمون @drawer_open@): پرسش با برچسب «شما گفتید» و متن «خلاصه داشبورد مدیرعامل»؛ پاسخ با نشان «راستی‌آزمایی‌شده»، نام مدل ⟦mock-primary⟧ و دکمه‌ی «پخش صدا» (بی‌صدا). گام ۳: پرسش بی‌درنگ فرستاده می‌شود و نتیجه همان است. گام ۴: پس از ⟦8⟧ ثانیه «چیزی شنیده نشد؛ دوباره بگویید.»؛ میکروفون بسته می‌شود و هیچ پرسشی ثبت نمی‌شود (طولانی‌ترین پرسش ⟦15⟧ ثانیه است؛ بیشتر از آن همان‌جا فرستاده می‌شود). گام ۵: نوار صدای کشو به ترتیب: «در حال شنیدن…»؛ پس از شنیدن گفتار «می‌شنوم… پس از مکثی کوتاه ارسال می‌شود»؛ «در حال فکر کردن…»؛ «در حال گفتن… برای صحبت، میکروفون را بزنید»؛ «اگر پرسش دیگری دارید، بگویید» با شمارنده؛ و در پایان «برای گفتن، میکروفون را بزنید». دکمه‌ی میکروفون کشو هنگام شنیدن قرمز و با نوشته‌ی «ارسال» (راهنما «ارسال حالا (یا مکث کنید)») است، هنگام گفتن «صحبت کنید» (راهنما «قطع پاسخ و صحبت») و هنگام فکر کردن خاکستری با «…»؛ در حالت عادی «میکروفون» (راهنما «بزنید و بگویید (Esc برای توقف)»). با خاموش بودن «گفت‌وگوی پیوسته» پنجره‌ی «پرسش بعدی» باز نمی‌شود. (تشخیص درست گفتار فارسی را فقط یک مدل واقعی نشان می‌دهد: ★ پرسش‌های شرکت.)")

t("v_ptt", "S8", "کلید Space و نگه‌داشتن (فشار و گفتن)، قطع پاسخ هنگام گفتن و کلید Esc", CEO,
  [DASH + ": کشو بسته باشد و مکان‌نما در هیچ کادری نباشد (روی بخش خالی صفحه کلیک کنید). کلید Space را پایین نگه دارید، بیش از نیم ثانیه جمله‌ای بگویید و رها کنید.",
   "Space را کوتاه بزنید (کمتر از نیم ثانیه)، جمله‌ای بگویید و ساکت بمانید. دوباره Space را کوتاه بزنید، جمله‌ای بگویید و بی‌انتظار مکث دوباره Space بزنید.",
   "سرور «متن به گفتار» را غیرفعال کنید (برای زمان بیشتر؛ پس از آزمون فعالش کنید). نماد بلندگوی «شاخص‌های اصلی» را بزنید و هنگام خواندن Space را کوتاه بزنید.",
   "در کادر پرسش کشو و در کادر فیلتر یک جدول جزئیات Space بزنید و چند حرف بنویسید.",
   "روی بخش خالی صفحه Shift+Space، Ctrl+Space و Alt+Space را امتحان کنید. سپس با Tab به یک دکمه‌ی صفحه (مثلاً «بازخوانی» بالای صفحه) بروید و Space و بعد Enter بزنید.",
   "کشو و یکی از جدول‌های جزئیات را باز بگذارید. میکروفون را بزنید و هنگام شنیدن Esc بزنید؛ دوباره Esc بزنید. همین را هنگام گفتن پاسخ، در پنجره‌ی «پرسش بعدی» و هنگام خواندن یک بخش تکرار کنید.",
   "(ماوس) دکمه‌ی میکروفون کپسول را بیش از نیم ثانیه نگه دارید و رها کنید؛ سپس یک کلیک کوتاه روی آن بزنید."],
  "گام ۱: با نگه‌داشتن Space کارت «در حال شنیدن…» باز می‌شود و صفحه پایین نمی‌رود؛ با رها کردن (پس از دست‌کم ⟦0.45⟧ ثانیه) پرسش بی‌درنگ، بدون صبر برای مکث، فرستاده می‌شود و پاسخ مانند آزمون @v_listen@ می‌آید. گام ۲: ضربه‌ی کوتاه Space گوش‌دادن را شروع می‌کند و تا مکث ادامه دارد؛ Space دوم هنگام گوش‌دادن همان لحظه می‌فرستد. گام ۳: Space هنگام خواندن، خواندن را می‌ایستاند (نماد بلندگو برمی‌گردد) و بلافاصله گوش‌دادن را شروع می‌کند. گام ۴: در کادرهای نوشتنی Space فاصله می‌نویسد و صدا شروع نمی‌شود. گام ۵: Shift+Space، Ctrl+Space و Alt+Space صدا را شروع نمی‌کنند. روی دکمه‌ی فوکوس‌شده Space دکمه را نمی‌زند و فقط صدا را شروع می‌کند؛ Enter دکمه را می‌زند. گام ۶: Esc هنگام گوش‌دادن، گفتن، پنجره‌ی «پرسش بعدی» یا خواندن، همان را می‌ایستاند و هیچ پرسشی نمی‌رود و پاسخی که در راه بوده گفته نمی‌شود؛ کشو و جدول باز می‌مانند. Esc دوم آن‌ها را می‌بندد. گام ۷: نگه‌داشتن بیش از نیم ثانیه مثل Space نگه‌داشته می‌شود (رها کردن می‌فرستد)؛ کلیک کوتاه مثل ضربه‌ی کوتاه است و کلیک بعدی هنگام گوش‌دادن می‌فرستد.")

t("v_act", "S8", "فرمان‌های صوتی کشو (چهار دکمه) و کارهای دستیار: باز کردن صفحه، خواندن هشدارها، فرمان نامفهوم و قطع پاسخ", CEO,
  [DASH + ": کشو را باز کنید. در گروه «فرمان‌های صوتی؛ بگویید یا بزنید» روی «باز کن سفارش‌های عقب‌افتاده تولید» بزنید. پاسخ، خط زیر آن و رفتار صفحه را ببینید.",
   "با کلید برگشت مرورگر به داشبورد برگردید، کشو را باز کنید و «بخوان هشدارها» را بزنید.",
   "«تحلیل کن بخش فروش» و «نشانم بده پروژه‌های قرمز» را بزنید و پاسخ‌ها را بخوانید.",
   "سرور «متن به گفتار» را غیرفعال کنید. دوباره «باز کن سفارش‌های عقب‌افتاده تولید» را بزنید و هنگام گفتن پاسخ Esc بزنید. (اگر مرورگر صدای فارسی دارد، پاسخ را با آن می‌گوید و فرصت بیشتر است.) سپس سرور را دوباره فعال کنید.",
   "(ویژه‌ی مدیر فنی) با دستورهای بخش «درخواست صوتی با PowerShell» راهنما فایل ⟦ui-open.wav⟧ را بسازید و دو بار به ⟦POST /api/v1/ai/voice⟧ بفرستید: یک بار با ⟦uiContext.page=/ceo⟧ و یک بار بدون آن."],
  "گام ۱: در فهرست کشو پرسش با برچسب «شما» و متن دکمه می‌آید؛ پاسخ «سفارش‌های تولید را باز می‌کنم.» با نشان «راستی‌آزمایی‌شده»؛ زیر آن «✓ صفحه‌ی «باز کردن صفحه‌ی تولید» پس از پایان پاسخ باز می‌شود». پاسخ گفته می‌شود و پس از پایان آن برنامه به سفارش‌های تولید (⟦/production/orders⟧) می‌رود؛ مدل آزمایشی «عقب‌افتاده» را نمی‌فهمد و همیشه همین صفحه را باز می‌کند. دکمه‌ی فرمان پس از زدن، تا رسیدن پاسخ (و هنگام گوش‌دادن میکروفون) اثر ندارد؛ و چون پرسش با دکمه فرستاده شده، میکروفون پس از پاسخ دوباره باز نمی‌شود (پنجره‌ی «پرسش بعدی» فقط پس از پرسشی می‌آید که با میکروفون گفته شود). گام ۲: پاسخ «هشدارها را می‌خوانم.» و خط «✓ هشدارها خوانده می‌شود»؛ نخست پاسخ و سپس متن هشدارها (آزمون @speakalerts@) گفته می‌شود و صفحه به ستون هشدارها می‌رود (در پنجره‌ی کم‌عرض کشو پیش از آن بسته می‌شود). گام ۳: «تحلیل کن بخش فروش» پاسخ «طبق نتایج سامانه: …» می‌گیرد، چون مدل آزمایشی واژه‌ی «روش» درون «فروش» را جست‌وجوی سند می‌داند؛ تنها عدد، شمار سندهای یافت‌شده است («0» اگر سند کنترل‌شده‌ای ثبت نشده). هیچ تحلیلی آغاز نمی‌شود و خط «✓» نیست. «نشانم بده پروژه‌های قرمز» پاسخ «%s» می‌گیرد و صفحه جابه‌جا نمی‌شود. (با یک مدل واقعی این دو فرمان باید «✓ تحلیل بخش «فروش» آغاز شد؛ نتیجه در همان بخش می‌آید» و نمایش بخش پروژه‌ها را بدهند؛ پذیرش مدل واقعی: ★ پرسش‌های شرکت.) گام ۴: Esc گفتن را می‌ایستاند و برنامه در داشبورد می‌ماند، هرچند خط «✓ … پس از پایان پاسخ باز می‌شود» در فهرست مانده است؛ رفتن به صفحه‌ی دیگر فقط پس از گفتن کامل پاسخ انجام می‌شود. گام ۵: با ⟦uiContext.page=/ceo⟧: success برابر true؛ transcript «باز کن سفارش‌های تولید»؛ answer «سفارش‌های تولید را باز می‌کنم.»؛ toolCalls یک ردیف ⟦ui_navigate⟧ با allowed برابر true؛ actions یک ردیف با type ⟦navigate⟧، link ⟦/production/orders⟧ و title «باز کردن صفحه‌ی تولید»؛ verified برابر true؛ degraded برابر false؛ audioBase64 پر. بدون ⟦uiContext.page⟧: actions خالی و answer «این ابزار برای شما در دسترس نیست.» (ابزارهای کار روی صفحه فقط وقتی به مدل پیشنهاد می‌شوند که صفحه‌ی کاربر فرستاده شده باشد)." % GREETING)

t("v_errors", "S8", "خطاهای صوتی: اجازه‌ی میکروفون داده نشد، چیزی شنیده نشد، رفتن از صفحه هنگام ضبط", CEO,
  [DASH + ": در مرورگر میکروفون را برای نشانی برنامه «Block» (مسدود) کنید (قفل کنار نوار آدرس ← تنظیمات سایت ← میکروفون). دکمه‌ی میکروفون کپسول را بزنید؛ سپس کشو را باز کنید و دکمه‌ی میکروفون کشو را بزنید. اجازه را دوباره به «Allow» برگردانید.",
   "میکروفون کپسول را بزنید و ⟦8⟧ ثانیه هیچ نگویید. همین را با میکروفون کشو انجام دهید.",
   "میکروفون را بزنید و هنگام گوش‌دادن کلید برگشت مرورگر را بزنید (یا از منو به صفحه‌ی دیگری بروید). نشانگر ضبط مرورگر را ببینید و به داشبورد برگردید.",
   "پس از هر گام، نشانگر ضبط مرورگر (نقطه‌ی قرمز یا نماد میکروفون روی زبانه) را ببینید."],
  "گام ۱: «اجازه استفاده از میکروفون داده نشد.»؛ در کپسول کارت حدود پنج ثانیه با این جمله می‌ماند و در کشو همین جمله زیر فهرست گفت‌وگو (نوار صدا) دیده می‌شود؛ حالت میکروفون به عادی برمی‌گردد و پرسش تایپی کار می‌کند. گام ۲: پس از ⟦8⟧ ثانیه «چیزی شنیده نشد؛ دوباره بگویید.»؛ میکروفون بسته می‌شود و پرسشی ثبت نمی‌شود. گام ۳: با رفتن از صفحه هنگام ضبط، ضبط بی‌درنگ قطع می‌شود و هیچ چیزی فرستاده نمی‌شود؛ پس از برگشتن صفحه آرام است و پرسش تازه‌ای می‌شود پرسید. گام ۴: نشانگر ضبط مرورگر تنها هنگام «در حال شنیدن…» روشن است و پس از هر پایان، خطا، Esc، یا رفتن از صفحه فوراً خاموش می‌شود (هیچ ضبط پنهانی نیست). خرابی سرور «گفتار به متن» یا «متن به گفتار» در آزمون @speechdown@ است.")
